//! Text length constraints distinguish native edits from script value writes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<body><form id=form><input id=input name=q minlength=3><textarea id=area name=body minlength=4></textarea><button id=button>Submit</button></form></body>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://text-length.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn node(d:&Document,id:&str)->usize{(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some(id)).unwrap()}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,source:&str){p.begin_job();p.runtime.execute(source,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn text_length_validation_native_utf16_edits_and_script_reset_are_distinct(){
 let(mut d,mut f,mut p)=fixture();let input=node(&d,"input");let area=node(&d,"area");f.controls.get_mut(&input).unwrap().insert("😀");f.controls.get_mut(&area).unwrap().insert("A\r\n😀");run(&mut d,&mut f,&mut p,"var x=document.getElementById('input'),a=document.getElementById('area'),v=x.validity,av=a.validity;if(!v.tooShort||v.tooLong||v.valid||x.checkValidity()!==false||x.validationMessage!=='Lengthen this field: q.')throw 'native UTF16 short';if(av.tooShort||av.tooLong||!av.valid||a.value.length!==4)throw 'normalized UTF16 area';x.value='😀';if(v.tooShort||v.tooLong||!v.valid||x.validationMessage||!x.checkValidity())throw 'script excludes length';a.maxLength=3;if(!av.tooLong||av.tooShort||av.valid||a.validationMessage!=='Shorten this field: body.')throw 'current max after user edit';a.value=a.value;if(av.tooLong||!av.valid)throw 'equal script write excludes length';document.getElementById('form').reset();if(v.tooShort||av.tooShort||v.tooLong||av.tooLong||!v.valid||!av.valid)throw 'reset length state';");
}
#[test]
fn text_length_validation_form_and_native_submission_include_user_length_errors(){
 let(mut d,mut f,mut p)=fixture();let input=node(&d,"input");f.controls.get_mut(&input).unwrap().insert("A");run(&mut d,&mut f,&mut p,"var x=document.getElementById('input'),form=document.getElementById('form'),invalid=0;x.addEventListener('invalid',function(e){if(!e.isTrusted)throw 'trusted invalid';invalid++;e.preventDefault();});if(form.checkValidity()!==false||invalid!==1)throw 'form length invalid';");let owner=node(&d,"form");p.begin_job();let(_,invalid,unhandled)=p.validate_native_submission(&mut d,&mut f,owner,None).unwrap();assert!(invalid);assert!(unhandled.is_none());run(&mut d,&mut f,&mut p,"x.value='A';if(!form.checkValidity()||x.validity.tooShort)throw 'script length recovery';");
}

#[test]
fn text_length_validation_prefixes_large_bounds_and_barred_flags(){
 let(mut d,mut f,mut p)=fixture();let input=node(&d,"input");f.controls.get_mut(&input).unwrap().insert("A");run(&mut d,&mut f,&mut p,"var x=document.getElementById('input'),v=x.validity;x.setAttribute('minlength','999999999999999999999999999999');x.setAttribute('maxlength','999999999999999999999999999999');if(!v.tooShort||v.tooLong)throw 'huge valid bounds';x.setAttribute('minlength','  +0002tail');if(!v.tooShort)throw 'HTML prefix';for(var value of ['-1','-0tail','no digits','']){x.setAttribute('minlength',value);if(v.tooShort)throw 'absent or zero minimum';}x.minLength=3;x.readOnly=true;if(!v.tooShort||v.valid||x.willValidate||!x.checkValidity()||x.validationMessage)throw 'readonly independent flags';x.readOnly=false;x.disabled=true;if(!v.tooShort||v.valid||!x.checkValidity())throw 'disabled independent flags';x.disabled=false;x.maxLength=0;if(!v.tooLong||!v.tooShort||v.valid)throw 'independent conflicting bounds';x.value='A';if(v.tooLong||v.tooShort||!v.valid)throw 'script excludes both lengths';");
}
#[test]
fn text_length_validation_empty_user_value_and_defaults_do_not_fake_user_changes(){
 let(mut d,mut f,mut p)=fixture();let input=node(&d,"input");let area=node(&d,"area");f.controls.get_mut(&input).unwrap().insert("A");f.controls.get_mut(&area).unwrap().insert("A");run(&mut d,&mut f,&mut p,"var x=document.getElementById('input'),a=document.getElementById('area'),v=x.validity,av=a.validity;var set=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;x.defaultValue='Default';a.defaultValue='Default area';if(!v.tooShort||!av.tooShort||x.value!=='A'||a.value!=='A')throw 'dirty defaults preserve user change';set.call(x,'A');a.value='A';if(v.tooShort||av.tooShort||!v.valid||!av.valid)throw 'saved equal script writes';document.getElementById('form').reset();if(v.tooShort||av.tooShort||x.value!=='Default'||a.value!=='Default area')throw 'reset defaults';");{let c=f.controls.get_mut(&input).unwrap();c.value.anchor=0;c.value.cursor=c.value.chars.len();c.insert("");}run(&mut d,&mut f,&mut p,"if(x.value!==''||v.tooShort||v.tooLong||!v.valid)throw 'empty optional user value';");
}
#[test]
fn text_length_validation_failed_script_write_and_reset_preserve_user_state(){
 let(mut d,mut f,mut p)=fixture();let input=node(&d,"input");f.controls.get_mut(&input).unwrap().insert("A");run(&mut d,&mut f,&mut p,"var x=document.getElementById('input'),v=x.validity,form=document.getElementById('form');if(!v.tooShort)throw 'user baseline';");let before=(format!("{:?}",d.nodes),p.state.retained,p.state.dom_commits,f.controls[&input].value.text());for script in ["x.value='Replacement';","form.reset();"]{p.begin_job();p.state.copy_work=0;p.state.host_work=0;assert!(p.runtime.execute(script,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!((format!("{:?}",d.nodes),p.state.retained,p.state.dom_commits,f.controls[&input].value.text()),before);assert!(f.controls[&input].last_value_change_user);p.begin_job();run(&mut d,&mut f,&mut p,"if(!v.tooShort||v.valid)throw 'refusal retains user state';");}run(&mut d,&mut f,&mut p,"x.value='A';if(v.tooShort||!v.valid)throw 'fresh setter recovery';form.reset();if(v.tooShort||!v.valid)throw 'fresh reset recovery';");
}
#[test]
fn text_length_validation_request_submit_and_no_validate_keep_distinct_behavior(){
 let(mut d,mut f,mut p)=fixture();let input=node(&d,"input");f.controls.get_mut(&input).unwrap().insert("A");run(&mut d,&mut f,&mut p,"var x=document.getElementById('input'),form=document.getElementById('form'),b=document.getElementById('button'),invalid=0,submitted=0;x.addEventListener('invalid',function(e){if(!e.isTrusted)throw 'trusted invalid';invalid++;e.preventDefault();});form.addEventListener('submit',function(e){if(!e.isTrusted||e.submitter!==b)throw 'trusted submit';submitted++;e.preventDefault();});form.requestSubmit(b);if(invalid!==1||submitted!==0)throw 'length blocks request';form.noValidate=true;form.requestSubmit(b);if(submitted!==1||invalid!==1||form.checkValidity()!==false||invalid!==2)throw 'no validate separation';form.noValidate=false;x.value='A';form.requestSubmit(b);if(submitted!==2||invalid!==2||x.validity.tooShort)throw 'script value submission recovery';");
}
#[test]
fn text_length_validation_ordered_snapshot_retains_later_repaired_target(){
 let(mut d,mut f,mut p)=fixture();for id in ["input","area"]{let n=node(&d,id);f.controls.get_mut(&n).unwrap().insert("A");}run(&mut d,&mut f,&mut p,"var x=document.getElementById('input'),a=document.getElementById('area'),form=document.getElementById('form'),order='';x.addEventListener('invalid',function(){order+='I';a.value='Ready';});a.addEventListener('invalid',function(e){if(!e.isTrusted||a.validity.tooShort)throw 'saved target current flags';order+='A';});if(form.checkValidity()!==false||order!=='IA'||a.validity.tooShort)throw 'ordered length snapshot';if(form.checkValidity()!==false||order!=='IAI')throw 'fresh length snapshot';x.value='A';if(!form.checkValidity())throw 'snapshot recovery';");
}
#[test]
fn text_length_validation_fatal_listener_keeps_committed_script_change_and_unwinds(){
 let(mut d,mut f,mut p)=fixture();let input=node(&d,"input");f.controls.get_mut(&input).unwrap().insert("A");run(&mut d,&mut f,&mut p,"var x=document.getElementById('input'),form=document.getElementById('form'),listener=function(){x.value='B';for(var i=0;i<10000;i++)x.getAttribute('id');};x.addEventListener('invalid',listener);");p.begin_job();p.state.host_work=2000;let error=p.runtime.execute("form.checkValidity();",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("work")||error.contains("allowance"),"{error}");assert_eq!(f.controls[&input].value.text(),"B");assert!(!f.controls[&input].last_value_change_user);assert!(p.state.form_validations.is_empty()&&p.state.synthetic_dispatches.is_empty()&&p.state.form_requests.is_empty());run(&mut d,&mut f,&mut p,"x.removeEventListener('invalid',listener);if(x.validity.tooShort||!x.validity.valid||!form.checkValidity())throw 'committed script flag recovery';");
}
